<template><section class="detail"><div class="page-heading"><el-button text :icon="ArrowLeft" @click="router.push({name:'EnterpriseEmployees'})">返回员工列表</el-button></div>

<el-skeleton v-if="detailLoading" :rows="3" animated/>
<el-alert v-else-if="detailError" type="error" :title="detailError" :closable="false" class="notice"><el-button size="small" @click="loadDetail">重试</el-button></el-alert>
<template v-else-if="detail">
<div class="profile-head"><div class="avatar">{{ avatarLetter }}</div><div class="profile-meta"><h2>{{ detail.email.split('@')[0] }} <el-tag :type="statusType(detail.status)" size="small">{{ statusLabel(detail.status) }}</el-tag></h2><p>{{ maskDots }} · {{ maskEmail(detail.email) }} · {{ detail.department_name || '未分配部门' }}</p></div><div class="actions"><el-button :icon="Edit" :disabled="detail.status==='terminated'" @click="openEdit">编辑资料</el-button><el-button type="danger" plain :disabled="detail.status==='terminated'" @click="terminate">标记离职</el-button><el-button type="primary" plain @click="router.push({path:'/enterprise/admin/allocation',query:{employee_id:String(detail.id)}})">配置 allocation</el-button><el-button plain @click="router.push('/enterprise/admin/keys')">查看员工 Key</el-button></div></div>

<el-tabs v-model="activeTab" class="detail-tabs" @tab-change="onTabChange">
  <el-tab-pane label="基本信息" name="profile">
    <div class="info-list">
      <div class="info-row"><span class="key">员工 ID</span><span>{{ maskDots }}</span></div>
      <div class="info-row"><span class="key">企业邮箱</span><span>{{ maskEmail(detail.email) }}</span></div>
      <div class="info-row"><span class="key">部门归属</span><span>{{ detail.department_name || '未分配' }}</span></div>
      <div class="info-row"><span class="key">状态</span><span><el-tag :type="statusType(detail.status)" size="small">{{ statusLabel(detail.status) }}</el-tag></span></div>
      <div class="info-row"><span class="key">首次改密</span><span>{{ detail.must_change_password ? '待完成' : '已完成' }}</span></div>
      <div class="info-row"><span class="key">加入时间</span><span>{{ formatDate(detail.created_at) }}</span></div>
      <div class="info-row" v-if="detail.terminated_at"><span class="key">离职时间</span><span>{{ formatDate(detail.terminated_at) }}</span></div>
    </div>
  </el-tab-pane>

  <el-tab-pane label="额度与用量" name="usage">
    <el-skeleton v-if="usageLoading && !usageLoaded" :rows="4" animated/>
    <el-alert v-else-if="usageError" type="error" :title="usageError" :closable="false" class="notice"><el-button size="small" @click="loadUsage">重试</el-button></el-alert>
    <template v-else>
      <div class="metric-strip"><div class="metric"><span>请求数</span><strong>{{ usageSummary?.total_requests ?? 0 }}</strong></div><div class="metric"><span>用量积分</span><strong>{{ usageSummary?.total_usage_credit ?? '0' }}</strong></div><div class="metric"><span>配置积分</span><strong>{{ employeeConfiguredCredit }}</strong></div></div>
      <el-table v-loading="usageLoading" :data="usage.items" stripe><el-table-column prop="request_at" label="请求时间" width="190"><template #default="{row}">{{ formatDate(row.request_at) }}</template></el-table-column><el-table-column prop="api_key_masked" label="Key" width="160"/><el-table-column prop="window_type" label="窗口" width="90"/><el-table-column prop="usage_credit" label="用量积分" width="140"/><el-table-column prop="classification" label="归属" width="120"><template #default="{row}">{{ row.classification==='employee'?'员工':'受控外部' }}</template></el-table-column></el-table>
      <el-empty v-if="!usageLoading && !usage.items.length" description="暂无用量记录"/>
      <el-pagination v-if="usage.total" v-model:current-page="usagePage" :page-size="pageSize" :total="usage.total" layout="total, prev, pager, next" @current-change="loadUsage"/>
    </template>
  </el-tab-pane>

  <el-tab-pane label="API Key" name="key">
    <el-skeleton v-if="detailLoading" :rows="3" animated/>
    <template v-else-if="detail.current_key">
      <div class="info-list">
        <div class="info-row"><span class="key">Key</span><span class="code-mask">{{ detail.current_key.masked_key }}</span></div>
        <div class="info-row"><span class="key">状态</span><span><el-tag :type="keyStatusType(detail.current_key.status)" size="small">{{ keyStatusLabel(detail.current_key.status) }}</el-tag></span></div>
        <div class="info-row"><span class="key">配额</span><span>{{ detail.current_key.quota_used }} / {{ detail.current_key.quota }}</span></div>
        <div class="info-row"><span class="key">限流（5h / 1d / 7d）</span><span>{{ detail.current_key.usage_5h }}/{{ detail.current_key.rate_limit_5h }} · {{ detail.current_key.usage_1d }}/{{ detail.current_key.rate_limit_1d }} · {{ detail.current_key.usage_7d }}/{{ detail.current_key.rate_limit_7d }}</span></div>
        <div class="info-row"><span class="key">创建时间</span><span>{{ formatDate(detail.current_key.created_at) }}</span></div>
      </div>
    </template>
    <el-empty v-else description="该员工当前没有可用的 API Key"/>
  </el-tab-pane>

  <el-tab-pane label="状态历史" name="history">
    <el-skeleton v-if="historyLoading && !historyLoaded" :rows="4" animated/>
    <el-alert v-else-if="historyError" type="error" :title="historyError" :closable="false" class="notice"><el-button size="small" @click="loadHistory">重试</el-button></el-alert>
    <template v-else>
      <div v-if="!history.items.length" class="empty-state"><el-empty description="暂无状态变更记录"/></div>
      <div v-else class="timeline"><div v-for="event in history.items" :key="event.id" class="event"><b>{{ eventLabel(event.event_type) }}</b><p>{{ formatDate(event.created_at) }} · {{ event.actor_ref }}</p></div></div>
      <el-pagination v-if="history.total" v-model:current-page="historyPage" :page-size="pageSize" :total="history.total" layout="total, prev, pager, next" @current-change="loadHistory"/>
    </template>
  </el-tab-pane>
</el-tabs>
</template>

<el-dialog v-model="editVisible" title="编辑员工" width="min(92vw, 500px)"><el-form label-position="top"><el-form-item label="邮箱"><el-input :model-value="detail?.email" disabled/></el-form-item><el-form-item label="部门"><el-select v-model="editDepartment" clearable placeholder="不分配部门"><el-option v-for="department in departments" :key="department.id" :label="department.name" :value="department.id"/></el-select></el-form-item></el-form><template #footer><el-button @click="editVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveEmployee">保存</el-button></template></el-dialog>
</section></template>
<script setup lang="ts">import{computed,onMounted,reactive,ref}from'vue';import{useRoute,useRouter}from'vue-router';import type{TagProps}from'element-plus';import{ElMessage,ElMessageBox}from'element-plus';import{ArrowLeft,Edit}from'@element-plus/icons-vue';import{enterpriseAPI,isEnterpriseEmployeeVersionConflict}from'@/api/enterprise';import type{EnterpriseDepartment,EnterpriseEmployeeDetail,EnterprisePaginated,EnterpriseWorkbenchAuditEvent,EnterpriseWorkbenchSummary,EnterpriseWorkbenchUsageRow}from'@/types/enterprise';const route=useRoute(),router=useRouter();const employeeId=computed(()=>Number(route.params.id));const detail=ref<EnterpriseEmployeeDetail>(),detailLoading=ref(false),detailError=ref(''),departments=ref<EnterpriseDepartment[]>([]),editVisible=ref(false),editDepartment=ref<number|null>(null),saving=ref(false),activeTab=ref('profile'),pageSize=ref(20);const usage=reactive<EnterprisePaginated<EnterpriseWorkbenchUsageRow>>({items:[],total:0,page:1,page_size:20,pages:1}),usageSummary=ref<EnterpriseWorkbenchSummary>(),usageLoading=ref(false),usageError=ref(''),usageLoaded=ref(false),usagePage=ref(1);const history=reactive<EnterprisePaginated<EnterpriseWorkbenchAuditEvent>>({items:[],total:0,page:1,page_size:20,pages:1}),historyLoading=ref(false),historyError=ref(''),historyLoaded=ref(false),historyPage=ref(1);const maskDots='••••••••••';const employeeConfiguredCredit=computed(()=>usageSummary.value?.employee_summaries?.find(s=>s.employee_id===employeeId.value)?.configured_credit??'0');const avatarLetter=computed(()=>detail.value?.email?.[0]?.toUpperCase()||'?');const maskEmail=(email:string)=>{const at=email.indexOf('@');if(at<=0)return'***';return`${email[0]}***${email.slice(at)}`};const statusLabel=(s:string)=>({active:'在职',disabled:'停用',terminated:'已离职'}[s]||s);const statusType=(s:string):TagProps['type']=>s==='active'?'success':s==='disabled'?'warning':'info';const keyStatusLabel=(s:string)=>({active:'启用',disabled:'已停用',quota_exhausted:'配额耗尽',expired:'已过期'}[s]||s);const keyStatusType=(s:string):TagProps['type']=>s==='active'?'success':s==='disabled'?'info':'warning';const eventLabel=(t:string)=>({'employee.created':'创建员工','employee.updated':'资料更新','employee.terminated':'标记离职','employee.update_rejected':'更新被拒绝（版本冲突）'}[t]||t);const formatDate=(value?:string)=>value?new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value)):'-';async function loadDetail(){detailLoading.value=true;detailError.value='';try{[detail.value,departments.value]=await Promise.all([enterpriseAPI.getEmployee(employeeId.value),enterpriseAPI.listDepartments()])}catch(error){detailError.value=(error as{message?:string})?.message||'员工详情加载失败'}finally{detailLoading.value=false}}async function loadUsage(){usageLoading.value=true;usageError.value='';try{const[rows,summary]=await Promise.all([enterpriseAPI.listWorkbenchUsage({employee_id:employeeId.value,page:usagePage.value,page_size:pageSize.value}),enterpriseAPI.getWorkbenchSummary({employee_id:employeeId.value})]);Object.assign(usage,rows);usageSummary.value=summary;usageLoaded.value=true}catch(error){usageError.value=(error as{message?:string})?.message||'额度与用量加载失败'}finally{usageLoading.value=false}}async function loadHistory(){historyLoading.value=true;historyError.value='';try{Object.assign(history,await enterpriseAPI.listWorkbenchAuditEvents({employee_id:employeeId.value,page:historyPage.value,page_size:pageSize.value}));historyLoaded.value=true}catch(error){historyError.value=(error as{message?:string})?.message||'状态历史加载失败'}finally{historyLoading.value=false}}function onTabChange(){if(activeTab.value==='usage'&&!usageLoaded.value)loadUsage();if(activeTab.value==='history'&&!historyLoaded.value)loadHistory()}function openEdit(){editDepartment.value=detail.value?.department_id??null;editVisible.value=true}async function handleEmployeeVersionConflict(error:unknown){if(!isEnterpriseEmployeeVersionConflict(error))throw error;ElMessage.warning('该员工已被其他管理员修改，已刷新为最新数据，请重新操作。');await loadDetail()}async function saveEmployee(){if(!detail.value)return;saving.value=true;try{await enterpriseAPI.updateEmployee(detail.value.id,{status:detail.value.status==='disabled'?'disabled':'active',department_id:editDepartment.value,version:detail.value.version});editVisible.value=false;ElMessage.success('员工信息已更新');await loadDetail()}catch(error){editVisible.value=false;await handleEmployeeVersionConflict(error)}finally{saving.value=false}}async function terminate(){if(!detail.value)return;await ElMessageBox.confirm(`确认将 ${detail.value.email} 标记为离职？该操作会撤销其会话。`,'员工离职',{type:'warning'});await enterpriseAPI.terminateEmployee(detail.value.id);ElMessage.success('员工已离职');await loadDetail()}onMounted(loadDetail);</script>
<style scoped>.detail{min-width:0}.page-heading{margin-bottom:12px}.notice{margin-bottom:16px}.profile-head{display:flex;align-items:center;gap:16px;padding:18px;background:#fff;border:1px solid #dce5e2;border-radius:6px;margin-bottom:16px}.avatar{width:48px;height:48px;border-radius:50%;background:#DBEAFE;color:#2563EB;font-size:18px;font-weight:800;display:grid;place-items:center;flex-shrink:0}.profile-meta{flex:1;min-width:0}.profile-meta h2{margin:0 0 6px;font-size:18px;display:flex;align-items:center;gap:8px}.profile-meta p{margin:0;color:#64748b;font-size:13px}.actions{display:flex;gap:8px;flex-shrink:0}.detail-tabs{background:#fff;border:1px solid #dce5e2;border-radius:6px;padding:0 18px 18px}.info-list{display:grid}.info-row{min-height:45px;display:grid;grid-template-columns:140px 1fr;align-items:center;border-bottom:1px solid #F0F1F3}.info-row:last-child{border-bottom:0}.info-row .key{color:#64748b}.code-mask{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-weight:700;letter-spacing:1px;color:#4B5563}.metric-strip{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-bottom:16px}.metric{padding:14px 16px;border:1px solid #dce5e2;border-radius:6px;background:#fff}.metric span{display:block;color:#64748b;font-size:12px}.metric strong{display:block;margin-top:6px;font-size:20px;color:#173f3d}.timeline{border-left:1px solid #D1D5DB;margin-left:7px;padding-left:20px}.event{position:relative;margin-bottom:17px}.event:before{content:"";position:absolute;left:-25px;top:3px;width:8px;height:8px;border-radius:50%;background:#2563EB;border:2px solid #fff;box-shadow:0 0 0 1px #93C5FD}.event b{font-size:13px}.event p{margin:4px 0 0;color:#64748b;font-size:12px}.empty-state{padding:24px 0}.el-pagination{justify-content:flex-end;margin-top:16px}@media(max-width:640px){.profile-head{flex-direction:column;align-items:flex-start}.actions{width:100%}.actions .el-button{flex:1}.info-row{grid-template-columns:110px 1fr}}</style>
